      'ctx.voter.vote.before_submit.title': 'Du er ved at indsende din stemme',
      'ctx.voter.vote.before_submit.body': 'Din stemme er privat og neutral — ingen andre ser, hvem du stemte på. Når den er sendt, kan du ikke stemme igen i den samme høring. Du kan senere verificere, at den blev registreret nøjagtigt som du afgav den.',
      'ctx.voter.vote.success.title': 'Stemme registreret!',
      'ctx.voter.vote.success.body': 'Din stemme er blevet registreret på en verificerbar måde. Gem din verifikationskode — den giver dig mulighed for senere at bekræfte, at din stemme blev talt korrekt.',
      'ctx.voter.results.title': 'Resultater',
